3. Modifica la funzione `getATH(ticker)` nel tuo progetto Google Script per utilizzare l'API CoinLayer come segue:

```javascript
function getATH(ticker) {
  var apiKey = "TUA_API_KEY";
  var url = "https://api.coinlayer.com/live?access_key=" + apiKey;
  var response = UrlFetchApp.fetch(url);
  var data = JSON.parse(response.getContentText());

  if (data.success === false) {
    Logger.log("Errore nella richiesta dell'ATH per il ticker: " + ticker);
    return "Errore";
  }

  var nome;
  var prezzoATH;
  var dataATH;
  var percentualeDaATH;
  var percentualeAATH;

  if (ticker in data.ath_info) {
    var coinData = data.ath_info[ticker];
    nome = coinData.asset_name;
    prezzoATH = coinData.ath_value.toString();
    dataATH = coinData.ath_date;
    percentualeDaATH = coinData.half_percent.toString();
    percentualeAATH = coinData.full_percent.toString();
  } else {
    return "Ticker non trovato";
  }

  return [nome, prezzoATH, dataATH, percentualeDaATH, percentualeAATH];
}
```

